import math
import time
import traceback

from lightlag_client import connect

BASE = (20.0, 20.0)
MAXT = 50
LAT = 4          # earliest execution = sent_tick + LAT
SPEED = 1.0      # conservative metres per tick for feasibility
MAXQ = 2         # max queued commands ahead of now


def log(*a):
    print(time.strftime("%H:%M:%S"), *a, flush=True)


def dist(a, b):
    return math.hypot(a[0] - b[0], a[1] - b[1])


class Autopilot:
    def __init__(self, tools):
        self.tools = tools
        self.mission = None
        self.reset(None)

    def reset(self, mission):
        self.mission = mission
        self.fixes = []        # (tick, x, y)
        self.cmds = []         # dicts: e, kind, vec
        self.sampled = set()
        self.seen_ticks = set()
        self.last_sample_sent = -99
        self.targets = []
        self.hz = []
        self.sand = []
        self.refresh_map()

    # ---------- world model ----------
    def refresh_map(self):
        try:
            m = self.tools.map()
        except Exception as e:
            log("map error", e)
            return
        self.targets = m.get("targets", [])
        self.hz = [(r["x1"], r["y1"], r["x2"], r["y2"]) for r in m.get("hazards", [])]
        self.sand = [(r["x1"], r["y1"], r["x2"], r["y2"]) for r in m.get("sand", [])]

    def in_rect(self, x, y, r, m=0.0):
        return r[0] - m <= x <= r[2] + m and r[1] - m <= y <= r[3] + m

    def in_hazard(self, x, y, m=0.0):
        return any(self.in_rect(x, y, h, m) for h in self.hz)

    def is_sand(self, x, y):
        return any(self.in_rect(x, y, r) for r in self.sand)

    def path_ok(self, a, b, m=0.7):
        d = dist(a, b)
        n = max(1, int(d / 0.25))
        for i in range(n + 1):
            t = i / n
            x = a[0] + (b[0] - a[0]) * t
            y = a[1] + (b[1] - a[1]) * t
            if dist((x, y), b) < 0.8:
                break
            if self.in_hazard(x, y, m):
                return False
            if not (0.5 <= x <= 39.5 and 0.5 <= y <= 39.5):
                return False
        return True

    def route(self, a, b):
        if self.path_ok(a, b):
            return [b]
        best = None
        for h in self.hz:
            x1, y1, x2, y2 = h
            c = 1.3
            for w in [(x1 - c, y1 - c), (x2 + c, y1 - c), (x1 - c, y2 + c), (x2 + c, y2 + c)]:
                if not (0.5 <= w[0] <= 39.5 and 0.5 <= w[1] <= 39.5):
                    continue
                if self.in_hazard(w[0], w[1], 0.3):
                    continue
                if self.path_ok(a, w) and self.path_ok(w, b):
                    cost = dist(a, w) + dist(w, b)
                    if best is None or cost < best[0]:
                        best = (cost, w)
        if best:
            return [best[1], b]
        return [b]

    # ---------- state estimate ----------
    def ingest(self, packets):
        for p in packets:
            try:
                tk = p["tick"]
            except Exception:
                continue
            if tk in self.seen_ticks:
                continue
            self.seen_ticks.add(tk)
            pos = p.get("position")
            if pos is not None:
                self.fixes.append((tk, pos[0], pos[1]))
            for s in p.get("sampled_targets", []) or []:
                sid = s if isinstance(s, str) else (s.get("id") if isinstance(s, dict) else None)
                if sid is not None:
                    self.sampled.add(sid)
            if not p.get("alive", True):
                log("ROVER DEAD", p)
        self.fixes.sort()

    def est_end(self):
        """Estimate of rover position after all commands sent so far."""
        if not self.fixes:
            return BASE
        k, x, y = self.fixes[-1]
        pend = [c for c in self.cmds if c["kind"] == "drive" and c["e"] > k]
        if not pend:
            lastE = max([c["e"] for c in self.cmds if c["kind"] == "drive"] + [-1])
            recent = [f for f in self.fixes if f[0] >= lastE][-4:]
            if recent:
                n = len(recent)
                return (sum(f[1] for f in recent) / n, sum(f[2] for f in recent) / n)
            return (x, y)
        dx = sum(c["vec"][0] for c in pend)
        dy = sum(c["vec"][1] for c in pend)
        return (x + dx, y + dy)

    def queue_len(self, T):
        return sum(1 for c in self.cmds if c["e"] > T)

    def next_exec(self, T):
        last = max([c["e"] for c in self.cmds] + [T + LAT])
        return max(T + LAT + 1, last + 1) if self.cmds else T + LAT + 1

    # ---------- commands ----------
    def send(self, T, cmd, kind, vec=(0.0, 0.0)):
        e = self.next_exec(T)
        if e > MAXT:
            return False
        try:
            self.tools.uplink([cmd])
        except ValueError as ex:
            log("uplink rejected", ex)
            return False
        self.cmds.append({"e": e, "kind": kind, "vec": vec})
        return True

    def drive_towards(self, T, pos, w):
        d = dist(pos, w)
        if d < 0.25:
            return False
        s = 0.33 if self.is_sand(pos[0], pos[1]) else 0.025
        m = min(d, 2.0) / (1.0 - s)
        m = max(m, 0.2)
        h = math.degrees(math.atan2(w[1] - pos[1], w[0] - pos[0]))
        dd = m * (1.0 - s)
        vec = (dd * math.cos(math.radians(h)), dd * math.sin(math.radians(h)))
        return self.send(T, {"action": "drive", "heading_deg": round(h, 2), "metres": round(m, 3)}, "drive", vec)

    def decide(self, T):
        if self.queue_len(T) >= MAXQ:
            return
        pos = self.est_end()
        goal = None
        for t in sorted(self.targets, key=lambda t: t.get("deadline_tick", 999)):
            if t["id"] in self.sampled or t.get("sampled"):
                continue
            if t.get("appear_tick", 0) > T:
                continue
            tp = (t["x"], t["y"])
            need = dist(pos, tp) / SPEED + dist(tp, BASE) / SPEED + LAT + 4
            if T + need > MAXT:
                continue
            goal = t
            break
        if goal is not None:
            tp = (goal["x"], goal["y"])
            if dist(pos, tp) < 0.6:
                if T - self.last_sample_sent >= 5:
                    if self.send(T, {"action": "sample"}, "sample"):
                        self.last_sample_sent = T
                        log("T", T, "sample", goal["id"], "est", [round(v, 2) for v in pos])
                return
            wps = self.route(pos, tp)
            self.drive_towards(T, pos, wps[0])
            return
        # go home
        if dist(pos, BASE) < 0.35:
            return
        wps = self.route(pos, BASE)
        self.drive_towards(T, pos, wps[0])

    def status(self, T):
        pos = self.est_end()
        log("T", T, "est", [round(v, 2) for v in pos], "fix", self.fixes[-1][1:] if self.fixes else None,
            "sampled", sorted(self.sampled), "q", self.queue_len(T))


def main():
    with connect("http://lightlag:8000/mcp") as tools:
        ap = Autopilot(tools)
        rules = tools.rules()
        log("rules ok, delay", rules.get("delay_ticks"), "max", rules.get("max_ticks"))
        try:
            ap.ingest(tools.telemetry_log())
        except Exception as e:
            log("telemetry err", e)
        ap.reset(None)
        while True:
            try:
                out = tools.advance(1)
            except Exception as e:
                log("advance error", e)
                traceback.print_exc()
                time.sleep(0.2)
                continue
            m = out.get("mission")
            if m != ap.mission:
                log("MISSION", m, "start")
                ap.reset(m)
            packets = []
            for v in out.values():
                if isinstance(v, list):
                    packets.extend(x for x in v if isinstance(x, dict) and "tick" in x)
            ap.ingest(packets)
            T = out.get("current_tick", 0)
            ap.refresh_map()
            try:
                ap.decide(T)
                if T % 3 == 0:
                    ap.status(T)
            except Exception as e:
                log("decide error", e)
                traceback.print_exc()
            if out.get("campaign_complete"):
                log("campaign complete")
                break


if __name__ == "__main__":
    main()
